// The exact Dolibarr driver remains in use. Only its fresh mysqli transport is
// subclassed to inject acknowledgements; all non-fault SQL reaches real MySQL.
class NsFaultMysqli extends mysqli {
 public $faultSql='';public $faultMode='';public $fired=false;public $readFailure=false;public $history=[];
 public function query(string $query,int $result_mode=MYSQLI_STORE_RESULT):mysqli_result|bool{
  $this->history[]=$query;
  if($this->readFailure&&$query==='SELECT 1 FROM `llx_societe` WHERE 1=0'){$this->readFailure=false;return false;}
  if(!$this->fired&&$query===$this->faultSql){$this->fired=true;if($this->faultMode==='after')parent::query($query,$result_mode);return false;}
  return parent::query($query,$result_mode);
 }
}
function ns_fault_db($sql,$phase,$readFailure=false){
 global$s;$d=ns_db();$old=$d->db;$m=new NsFaultMysqli('localhost','root','',$s['database'],0,$s['fixture'].'/mysql.sock');$identity=$m->query('SELECT @@socket socket,DATABASE() db')->fetch_assoc();nc_expect($identity['socket']===$s['fixture'].'/mysql.sock'&&$identity['db']===$s['database'],'Refuse unowned fault transport');$d->db=$m;$old->close();$m->faultSql=$sql;$m->faultMode=$phase;$m->readFailure=$readFailure;return[$d,$m];
}
