  $mustRetire=$command!=='COMMIT';
  if($mustRetire)nc_expect(!empty($p['connection_retired'])&&$d->db===null&&!$d->connected,'Uncertain preparation/start/rollback handle was reused');
  else{nc_expect(empty($p['connection_retired'])&&$d->db instanceof mysqli&&$d->connected,'Confirmed rollback recovery retired healthy handle');nc_expect(ns_state($d)===$before&&(int)$d->transaction_opened===0,'Recovery changed defaults/depth');$next=$service->currentPosition(17);nc_expect(ns_signature($next)===['verified_managed',100.0,40.0,20.0,60.0,40.0],'Next owned snapshot failed recovery');}
 }finally{ns_close($d);}
});
